  W += c[117] * 2.0225600000000000e+02; // A4
  W += c[118] * 2.0124799999999999e+02; // A4-
  W += c[119] * 2.2627799999999999e+02; // A4R5
  W += c[120] * 2.0225600000000000e+02; // FLTN
  W += c[121] * 6.6102999999999994e+01; // C5H6
  W += c[122] * 6.5094999999999999e+01; // C5H5
  W += c[123] * 8.1093999999999994e+01; // T-C5H5O
  W += c[124] * 8.0085999999999984e+01; // C5H4O
  W += c[125] * 8.1093999999999994e+01; // S-C5H5O
  W += c[126] * 1.1616299999999998e+02; // C9H8
